//! Per-map strategy table (formerly generated by harness/map_plans.py from local tournaments).
//! Keyed by `world::fingerprint` (exact: the draft sees the whole map). Unknown maps
//! use the general defaults (knob::DEFAULTS + the descriptor-based draft and knobs).


/// Draft preference: 0 default, 1 ranged first, 2 melee first, 3 Cassi & Issac first, 4 counter-pick,
/// 8 best-bot draft, 9 Tavi meta draft (draft.rs draft_prefs).
pub struct MapPlan {
    pub fingerprint: u32,
    pub name: &'static str,
    pub knobs: &'static [(usize, u8)],
    pub draft: u8,
}

/// Empty since engine 2.0.0: the 14 hand-made engine-1 plans that lived here were folded into
/// the searched per-map records (pack TAG_PLAN, league/plan_table.json) wherever the search
/// hadn't set that knob, so behaviour is unchanged and the per-map search is the only source.
pub const PLANS: &[MapPlan] = &[];

#[must_use]
pub fn lookup(fingerprint: u32) -> Option<&'static MapPlan> {
    PLANS.iter().find(|p| p.fingerprint == fingerprint)
}
